void RequestMediaSource(const std::wstring& source) {
    {
        std::lock_guard lock(g_mediaSourceMutex);
        g_dockOverrideAumid = source;
        ++g_dockOverrideRev;
    }
    if (g_mediaRefreshEvent) SetEvent(g_mediaRefreshEvent);
    g_layoutDirty = true;
}
void LockMediaSource(const std::wstring& source) {
    {
        std::lock_guard lock(g_mediaSourceMutex);
        g_preferredMediaSource = source;
        g_dockOverrideAumid.clear();
        ++g_dockOverrideRev;
    }
    if (g_mediaRefreshEvent) SetEvent(g_mediaRefreshEvent);
    g_layoutDirty = true;
}

void UpdateLyricsOutputDevice(IMMDevice* device) {
    bool bluetooth = false;
    ComPtr<IPropertyStore> store;
    if (device && SUCCEEDED(device->OpenPropertyStore(STGM_READ, &store))) {
        const PROPERTYKEY key = {{0xA45C254E,0xDF1C,0x4EFD,{0x80,0x20,0x67,0xD1,0x46,0xA8,0x50,0xE0}},24};
        PROPVARIANT value{};
        if (SUCCEEDED(store->GetValue(key, &value)))
            bluetooth = value.vt == VT_LPWSTR && value.pwszVal && _wcsnicmp(value.pwszVal,L"BTH",3)==0;
        PropVariantClear(&value);
    }
    g_defaultOutputIsBluetooth = bluetooth;
}

std::vector<int> DashboardTabs(const Settings& settings) {
    std::vector<int> tabs{0, 1};
    if (settings.weather) tabs.push_back(2);
    if (settings.hardwareMonitorModule) tabs.push_back(3);
    tabs.push_back(5);
    if (settings.fileTrayModule) tabs.push_back(4);
    if (settings.lyrics && g_lyricsTabAvailable.load()) {
        if (settings.lyricsPinnedFirst) tabs.insert(tabs.begin(), 6);
        else tabs.push_back(6);
    }
    return tabs;
}
int ActiveTabCount(const Settings& settings) { return static_cast<int>(DashboardTabs(settings).size()); }
int NormalizedTabIndex(const Settings& settings) {
    const int total = ActiveTabCount(settings), raw = g_idleTab.load();
    return ((raw % total) + total) % total;
}
int DashboardTabIndex(const Settings& settings, int id) {
    const auto tabs = DashboardTabs(settings);
    const auto it = std::find(tabs.begin(), tabs.end(), id);
    return it == tabs.end() ? -1 : static_cast<int>(it - tabs.begin());
}
int CurrentDashboardTab(const Settings& settings) { return DashboardTabs(settings)[NormalizedTabIndex(settings)]; }
int MediaTabIndex(const Settings& settings) { return DashboardTabIndex(settings, 0); }
int CalendarTabIndex(const Settings& settings) { return DashboardTabIndex(settings, 1); }
int HardwareMonitorTabIndex(const Settings& settings) { return DashboardTabIndex(settings, 3); }
int ClockTabIndex(const Settings& settings) { return DashboardTabIndex(settings, 5); }
int FileTrayTabIndex(const Settings& settings) { return DashboardTabIndex(settings, 4); }

void RefreshDashboardTabs(const Settings& settings, bool mediaAvailable) {
    static std::vector<int> previous;
    const int raw = g_idleTab.load();
    const int count = static_cast<int>(previous.size());
    const int selected = previous.empty() ? 0 : previous[((raw % count) + count) % count];
    g_lyricsTabAvailable = settings.media && mediaAvailable;
    const auto next = DashboardTabs(settings);
    if (next != previous) {
        const auto it = std::find(next.begin(), next.end(), selected);
        g_idleTab = it == next.end() ? MediaTabIndex(settings) : static_cast<int>(it - next.begin());
        previous = next;
        g_layoutDirty = true;
    }
}

// ── Localization (#35) ───────────────────────────────────────────────────────
// Every user-visible string in the island goes through Loc(). The English text
// doubles as the lookup key, so an untranslated string degrades to readable
// English rather than to a raw identifier, and adding a language means adding
// one column -- no key bookkeeping.
enum class UiLanguage {
    English,
    French,
    Spanish,
    German,
    Portuguese,
    Italian,
    Russian,
    Turkish,
    Hindi,
    ChineseSimplified,
    Japanese,
    Korean,
    Count,
};

std::atomic<int> g_uiLanguage{static_cast<int>(UiLanguage::English)};

UiLanguage LanguageFromTag(std::wstring_view tag) {
    struct Entry { const wchar_t* tag; UiLanguage lang; };
    static constexpr Entry kTags[] = {
        {L"en", UiLanguage::English},   {L"fr", UiLanguage::French},
        {L"es", UiLanguage::Spanish},   {L"de", UiLanguage::German},
        {L"pt", UiLanguage::Portuguese},{L"it", UiLanguage::Italian},
        {L"ru", UiLanguage::Russian},   {L"tr", UiLanguage::Turkish},
        {L"hi", UiLanguage::Hindi},     {L"zh", UiLanguage::ChineseSimplified},
        {L"ja", UiLanguage::Japanese},  {L"ko", UiLanguage::Korean},
    };
    if (tag.size() < 2) {
        return UiLanguage::English;
    }
    for (const Entry& e : kTags) {
        // Prefix match so "pt-BR" / "zh-Hans-CN" resolve to their base language.
        if (_wcsnicmp(tag.data(), e.tag, 2) == 0) {
            return e.lang;
        }
    }
    return UiLanguage::English;
}

// Resolves the "auto" language setting from the user's Windows UI language.
UiLanguage DetectSystemLanguage() {
    wchar_t name[LOCALE_NAME_MAX_LENGTH] = {};
    if (GetUserDefaultLocaleName(name, ARRAYSIZE(name)) > 0) {
        return LanguageFromTag(name);
    }
    return UiLanguage::English;
}

// ── Clock / date presentation (#61) ──────────────────────────────────────────

// Formats the time honouring the 12h/24h override and the seconds toggle.
// Windows' own locale formatting is used unless the user forced a mode, so the
// default keeps regional conventions (separators, AM/PM placement) intact.
std::wstring FormatIslandTime(const SYSTEMTIME& local, bool followSystem, bool use24Hour,
                              bool showSeconds) {
    wchar_t buffer[64] = {};

    if (followSystem) {
        const DWORD flags = showSeconds ? 0 : TIME_NOSECONDS;
        if (GetTimeFormatEx(LOCALE_NAME_USER_DEFAULT, flags, &local, nullptr, buffer,
                            ARRAYSIZE(buffer)) > 0) {
            return buffer;
        }
        return L"--:--";
    }

    // Explicit override: build the pattern rather than fighting locale flags.
    const wchar_t* pattern = use24Hour ? (showSeconds ? L"HH:mm:ss" : L"HH:mm")
                                       : (showSeconds ? L"h:mm:ss tt" : L"h:mm tt");
    if (GetTimeFormatEx(LOCALE_NAME_USER_DEFAULT, 0, &local, pattern, buffer,
                        ARRAYSIZE(buffer)) > 0) {
        return buffer;
    }
    return L"--:--";
}

// Formats the date. A custom pattern is passed straight to Windows, which
// already supports yyyy / MM / dd / MMM / MMMM / ddd / dddd and prints anything
// else literally -- so CJK patterns such as yyyy年MM月dd日 work as typed.
std::wstring FormatIslandDate(const SYSTEMTIME& local, const std::wstring& customFormat,
                              const wchar_t* fallbackPattern) {
    wchar_t buffer[128] = {};

    if (!customFormat.empty()) {
        if (GetDateFormatEx(LOCALE_NAME_USER_DEFAULT, 0, &local, customFormat.c_str(), buffer,
                            ARRAYSIZE(buffer), nullptr) > 0) {
            return buffer;
        }
        // An invalid pattern falls through to the default rather than showing
        // nothing at all.
    }

    if (GetDateFormatEx(LOCALE_NAME_USER_DEFAULT, 0, &local, fallbackPattern, buffer,
                        ARRAYSIZE(buffer), nullptr) > 0) {
        return buffer;
    }
    return std::wstring();
}

std::wstring FormatIslandStripClock(const SYSTEMTIME& local, const Settings& settings) {
    const auto time = FormatIslandTime(local, settings.clockFollowSystem,
                                      settings.use24HourClock, settings.showSeconds);
    wchar_t dateBuffer[64]{};
    const std::wstring date = GetDateFormatEx(L"en-US", 0, &local, L"ddd, MMM d",
        dateBuffer, ARRAYSIZE(dateBuffer), nullptr) > 0 ? dateBuffer :
        FormatIslandDate(local, L"MM-dd", L"MM-dd");
    return settings.dateFirst ? date + L" · " + time : time + L" · " + date;
}

float IdleDashboardExpandedAlpha(float height, float fullHeight = 144.0f) {
    // Keep large dashboard text out of the compact strip, regardless of width.
    float t = (height - 64.0f) / (fullHeight - 64.0f);
    t = (std::max)(0.0f, (std::min)(1.0f, t));
    return t * t * (3.0f - 2.0f * t);
}

